import {createLiteracy} from './literacy-ui.js';
import {topics,soundGroups,alphabet} from './pinyin-data.js';
import {curriculum} from './curriculum.js';
import {normalizePinyin,gradePinyin,shuffled,createSession,recordAnswer,updateMistake,localDay,dictationText} from './core.js';
import {load,save,mergeBackup,KEY} from './storage.js';
import {speak,stopAudio,startRecording,stopRecording,releaseRecording} from './media.js';
import {drawing} from './drawing.js';
import {audioMap} from './audio-map.js';
import {AUDIO_CACHE,SLOW_RATE,SPEECH_RATES} from './audio-settings.js';
import {pinyinFeedback,selectPractice,modeFor,canSubmit} from './learning.js';
const $=s=>document.querySelector(s),app=$('#app'),dialog=$('#dialog');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',leaf:'<path d="M20 4C8 2 3 7 4 13s11 10 16-9Z"/><path d="M4 21 15 10"/>',book:'<path d="M12 5v16M12 5C8 2 4 3 2 4v15c4-2 7-1 10 2 3-3 6-4 10-2V4c-2-1-6-2-10 1Z"/>',review:'<path d="M4 7a9 9 0 1 1-1 8M4 2v5h5"/><path d="M12 7v5l3 2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',back:'<path d="m14 5-7 7 7 7"/>',sound:'<path d="m11 4-6 5H2v6h3l6 5ZM15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',pencil:'<path d="m15 4 5 5M3 21l5-1L21 7a2 2 0 0 0-4-4L4 16Z"/>',check:'<path d="m5 12 4 4L20 5"/>',star:'<path d="m12 3 2.8 5.8 6.4.9-4.6 4.5 1 6.3L12 17.5l-5.6 3 1-6.3L2.8 9.7l6.4-.9Z"/>',settings:'<path d="M4 7h16M4 17h16M8 3v8m8 2v8"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',mic:'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6"/>',cloud:'<path d="M7 18a5 5 0 1 1 0-10 6 6 0 0 1 12-1 5.5 5.5 0 0 1 0 11"/><path d="M12 12v9m-3-3 3 3 3-3"/>',keyboard:'<rect x="2" y="5" width="20" height="14" rx="2"/><path d="M5 9h2m2 0h2m2 0h2m2 0h2M5 12h2m2 0h2m2 0h2m2 0h2M7 16h10"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',undo:'<path d="m8 4-5 5 5 5M3 9h10a7 7 0 0 1 0 14"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.leaf}</svg>`;
const btn=(label,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const initial=load();let state=initial.state,route={page:'home'},pad=null,toastTimer,offlineBusy=false,stale=false,recording=false,dialogReturn=null,demoEpoch=0;
const catalog=new Map();for(const t of topics)for(const q of t.items)catalog.set(q.id,{...q,kind:'pinyin',topicId:t.id,source:t.title,tip:q.explain||t.tip});
for(const b of curriculum)for(const u of b.units)for(const l of u.lessons)l.words.forEach((w,i)=>{const id=w.id||`${l.id}-w${i}`;catalog.set(id,{...w,sourceType:w.source,id,kind:'word',bookId:b.id,lessonId:l.id,source:l.title,tip:'先对照汉字，再检查声母、韵母和声调。'});});
const allPinyin=()=>[...catalog.values()].filter(q=>q.kind==='pinyin');
const lessonWords=l=>[...catalog.values()].filter(q=>q.lessonId===l.id&&(state.includeSupplements||q.sourceType==='textbook'));
const dueMistakes=()=>Object.values(state.mistakes).filter(m=>catalog.has(m.id)&&m.streak<3&&m.due<=Date.now());
const activeMistakes=()=>Object.values(state.mistakes).filter(m=>catalog.has(m.id)&&m.streak<3);
const literacy=createLiteracy({getState:()=>state,persist,go,refresh:render,notify,play,esc,btn,icon});
function persist(){if(stale)return false;const ok=save(state);if(!ok){$('#storage-warning').hidden=false;$('#storage-warning').textContent='本机空间不足，进度暂时无法保存。请到家长设置导出备份后释放空间。';}return ok;}
if(initial.error){$('#storage-warning').textContent=initial.error;$('#storage-warning').hidden=false;}
function notify(text){if(dialog.open){let local=dialog.querySelector('#dialog-status');if(!local){local=document.createElement('div');local.id='dialog-status';local.setAttribute('role','status');local.className='note-box mt';dialog.querySelector('.dialog-body').append(local);}local.textContent=text;}$('#notice').textContent=text;$('#notice').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#notice').classList.remove('visible'),5000);}
function cleanup(){demoEpoch++;pad?.destroy();pad=null;stopAudio();releaseRecording();recording=false;}
function go(page,other={}){cleanup();route={page,...other};render();window.scrollTo({top:0,behavior:'instant'});$('#main')?.focus({preventScroll:true});}
function openDialog(title,body){demoEpoch++;stopAudio();dialogReturn=document.activeElement;dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button data-action="close-dialog" aria-label="关闭">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!dialog.open)dialog.showModal();}
dialog.addEventListener('close',()=>{stopAudio();releaseRecording();recording=false;(dialogReturn?.isConnected?dialogReturn:$('#main'))?.focus({preventScroll:true});});
function titleBlock(kicker,title,sub,extra=''){return `<div class="headline"><div>${kicker?`<div class="kicker">${kicker}</div>`:''}<h1>${title}</h1><p>${sub}</p></div>${extra}</div>`;}
function shell(body){const page=route.page==='practice'?(state.session?.origin||'home'):route.page;const active=['topic','chart'].includes(page)?'pinyin':page==='lesson'?'books':page==='summary'?'home':page;
 return `<div class="shell"><aside class="sidebar"><div class="brand"><img src="icon.svg" alt=""><div><strong>拼音小花园</strong><small>每天，进步一点点</small></div></div><nav class="nav" aria-label="学习导航">${[['home','home','今日练习'],['pinyin','leaf','拼音专项'],['books','book','课文听写'],['review','review','错题小本'],['literacy','star','语文积累']].map(([p,i,t])=>`<button data-action="nav" data-page="${p}" class="${active===p?'active':''}" ${active===p?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${p==='review'&&dueMistakes().length?`<span class="badge">${dueMistakes().length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note">不着急，慢慢来。<br>每次听清一点，<br>每次写准一点。</div><button data-action="settings" class="row">${icon('settings')}家长设置</button></div></aside><div class="content"><div class="topbar"><span class="row">${icon('leaf')} 拼音小花园<span class="status-label"> / 让听写更有把握</span></span><div class="right"><span class="status-label"><span class="status-dot"></span>${navigator.onLine?'本机保存进度':'正在离线使用'}</span><button class="avatar" data-action="settings" aria-label="家长设置">${icon('settings')}</button></div></div><main id="main" tabindex="-1">${body}</main></div></div>`;
}
function home(){const today=state.history.filter(r=>localDay(new Date(r.at))===localDay()),done=new Set(state.history.map(r=>localDay(new Date(r.at)))).size;const mistakes=activeMistakes();return `${titleBlock('拼音小花园','今日练习','选一组开始，或者继续上次的练习。',`<span class="chip">${icon('sun')}每天 10 分钟</span>`)}
 ${state.session&&state.session.index<state.session.items.length?`<div class="note-box mb between"><span>你还有一组「${esc(state.session.title)}」没做完。</span>${btn('继续练习','resume','small primary')}</div>`:''}
 <section class="study-launch"><div><div class="kicker">慢慢听 · 仔细辨 · 独立写</div><h2>今日拼音练习</h2><p>${state.settings.count} 道题 · 先听辨，再独立拼写</p></div>${btn(`开始练习 ${icon('arrow')}`,'daily','primary')}</section>
 <section class="card mt row between wrap"><div><h2>语文积累</h2><p class="tip">日常古诗词 · 古诗词默写 · 看图写话 · 部首偏旁</p></div>${btn(`去积累 ${icon('arrow')}`,'nav','soft','data-page="literacy"')}</section>
 ${toneLab()}
 <div class="grid three stats mt"><div class="card mini-stat"><span class="stat-icon mint">${icon('pencil')}</span><div><strong>${today.length}<small style="font-size:14px"> 题</small></strong><p>今天已练习</p></div></div><div class="card mini-stat"><span class="stat-icon peach">${icon('review')}</span><div><strong>${dueMistakes().length}<small style="font-size:14px"> 题</small></strong><p>今天待复习</p></div></div><div class="card mini-stat"><span class="stat-icon lavender">${icon('star')}</span><div><strong>${done}<small style="font-size:14px"> 天</small></strong><p>累计学习</p></div></div></div>

 <div class="grid two mt"><button class="card link" data-action="nav" data-page="books"><div class="row"><span class="card-icon sky">${icon('book')}</span><h3>跟着课本，练听写</h3></div><p class="desc">二年级上册 · 下册<br>按课练习，按单元复习</p><span class="bottom"><span>人教统编 · 新课标修订版</span>${icon('arrow')}</span></button><button class="card link" data-action="nav" data-page="review"><div class="row"><span class="card-icon peach">${icon('review')}</span><h3>再见面，就更熟悉</h3></div><p class="desc">${mistakes.length?`还有 ${mistakes.length} 道题需要巩固。`:'错题会自动收进这里。'}<br>隔一段时间再练，看看是不是真会了</p><span class="bottom"><span>我的错题小本</span>${icon('arrow')}</span></button></div>
 <div class="note-box mt">${icon('info')}<span>给家长的小提示：先让孩子独立作答，再看答案。遇到混淆，听一遍对比、说出差别，比反复抄写更有方向。</span></div>`;}
function topicCard(t,color){const records=state.history.filter(r=>catalog.get(r.id)?.topicId===t.id);return `<button class="card link" data-action="topic" data-id="${t.id}"><div class="row between"><span class="chip ${color||t.color||'mint'}">${esc(t.kind||'专项')}</span>${icon('arrow')}</div><div class="sample">${esc(t.title)}</div><p class="desc">${esc(t.subtitle||t.tip)}</p><span class="bottom"><span>${t.items.length} 道练习</span><span>${records.length?`独立拼写 ${records.filter(r=>r.mode==='type').length} 次 · 需巩固 ${t.items.filter(q=>state.mistakes[q.id]?.streak<3).length} 题`:'还没开始'}</span></span></button>`;}
function pinyinPage(){const kinds=[...new Set(topics.map(t=>t.kind))];const list=route.kind?topics.filter(t=>t.kind===route.kind):topics;return `${titleBlock('听得清，才能写得准','拼音专项','从容易混淆的地方开始，每次只解决一个小问题。',btn(`${icon('book')}拼音全图谱`,'chart',''))}${toneLab()}<div class="filter-row"><button data-action="filter-topic" class="${!route.kind?'selected':''}">全部</button>${kinds.map(k=>`<button data-action="filter-topic" data-kind="${esc(k)}" class="${route.kind===k?'selected':''}">${esc(k)}</button>`).join('')}</div><div class="grid three">${list.map(t=>topicCard(t)).join('')}</div><div class="note-box mt">${icon('info')}<span>想看完整的声母、韵母和整体认读音节？${btn('打开拼音图谱','chart','small')}</span></div>`;}
function topicPage(){const t=topics.find(t=>t.id===route.id);if(!t)return pinyinPage();return `<div class="breadcrumb"><button data-action="nav" data-page="pinyin">拼音专项</button>${icon('chevron')}<span>${esc(t.title)}</span></div><div class="card topic-top"><div class="topic-symbol py ${t.color||'mint'}">${esc(t.title)}</div><div><div class="kicker">${esc(t.kind)}</div><h1>${esc(t.subtitle||'一起把它分清楚')}</h1><p class="tip mt-sm">${esc(t.tip)}</p></div></div><div class="section-head"><h2>今天想怎么练？</h2><span class="muted text-small">每组 ${Math.min(state.settings.count,t.items.length)} 题</span></div><div class="mode-list">${[['choose','sound','听音辨一辨','听完整的音，再选正确的拼音'],['type','keyboard','听音拼一拼','用拼音键盘作答，自动检查声调'],['write','pencil','听音写一写','在屏幕或纸上写，再对照批改']].map(([m,i,title,sub])=>`<button class="card link" data-action="start-topic" data-id="${t.id}" data-mode="${m}"><span class="card-icon ${t.color||'mint'}">${icon(i)}</span><h3>${title}</h3><p>${sub}</p><span class="bottom">开始练习 ${icon('arrow')}</span></button>`).join('')}</div><div class="section-head"><h2>先听听，再跟读</h2><small>点卡片播放例音</small></div><div class="word-grid">${t.items.slice(0,8).map(q=>`<button class="word" data-action="follow" data-id="${q.id}"><span class="py">${esc(q.pinyin)}</span><strong>${esc(q.text)}</strong><small>${icon('sound')} 跟读</small></button>`).join('')}</div>`;}
function chartPage(){const groups=[...soundGroups,{id:'alphabet',title:'字母表',items:alphabet,note:'26 个字母的大小写对照。字母名称与拼音读音不同，这一页只练认形，不用英语字母音替代拼音。'}];const group=groups.find(g=>g.id===route.group)||groups[0];return `${titleBlock('把知识放在一起','拼音全图谱','点一个字母或音节，听例字，再跟着读。',btn('返回专项','nav','',`data-page="pinyin"`))}<div class="filter-row">${groups.map(g=>`<button data-action="chart-group" data-id="${g.id}" class="${g.id===group.id?'selected':''}">${esc(g.title)} · ${g.items.length}</button>`).join('')}</div><div class="note-box mb">${icon('info')}<span>${esc(group.note||'播放的是完整例字的读音，用来帮助辨别和跟读。')}</span></div><div class="chart-grid">${group.items.map((s,i)=>group.id==='alphabet'?`<div class="card sound-card"><span class="py">${s.upper} ${s.lower}</span><small>大写 · 小写</small></div>`:`<button class="card sound-card" data-action="chart-sound" data-group="${group.id}" data-index="${i}"><span class="py">${esc(s.label)}</span><small>${esc(s.example)} · ${esc(s.pinyin)}</small></button>`).join('')}</div>`;}
function booksPage(){const b=curriculum.find(b=>b.id===state.book)||curriculum[0];const u=b.units.find(u=>u.number===state.unit)||b.units[0];return `${titleBlock('跟着课本，扎实一点','课文听写','选一课慢慢写，也可以练习整个单元。',btn('教材版本与来源','sources','small'))}<div class="row between wrap"><div class="tabs" aria-label="选择册次">${curriculum.map(x=>`<button data-action="book" data-id="${x.id}" class="${x.id===b.id?'selected':''}" aria-pressed="${x.id===b.id}">${esc(x.title)}</button>`).join('')}</div><span class="book-label">${b.id==='g2a'?'2024年审核通过 · 人教版':'统编语文 · 人民教育出版社'}</span></div><div class="row wrap mt-sm"><span class="tip">听写范围</span>${btn('只练教材词','word-range',!state.includeSupplements?'primary small':'small','data-include="false" aria-pressed="'+!state.includeSupplements+'"')}${btn('教材词＋补充词','word-range',state.includeSupplements?'primary small':'small','data-include="true" aria-pressed="'+state.includeSupplements+'"')}</div><div class="filter-row" aria-label="选择单元">${b.units.map(x=>`<button data-action="unit" data-number="${x.number}" class="${x.number===u.number?'selected':''}" aria-pressed="${x.number===u.number}">第${'一二三四五六七八'[x.number-1]}单元</button>`).join('')}</div><div class="card mb"><div class="row between wrap"><div><div class="kicker">第${'一二三四五六七八'[u.number-1]}单元</div><h2>${esc(u.title)}</h2><p class="tip mt-sm">${u.lessons.filter(l=>l.number!=='园地').length} 课 · ${u.lessons.reduce((a,l)=>a+lessonWords(l).length,0)} 个词 · 可选屏幕手写或纸上书写</p></div><div class="row wrap">${btn('抽练 10 词','unit-start','',`data-id="${u.id}" data-count="10"`)}${btn(`整单元听写 ${icon('arrow')}`,'unit-start','primary',`data-id="${u.id}" data-count="all"`)}</div></div></div><div class="lesson-list">${u.lessons.filter(l=>state.includeSupplements||l.number!=='园地').map(l=>`<button class="card lesson-row" data-action="lesson" data-id="${l.id}"><span class="lesson-number">${esc(l.number)}</span><div class="grow"><h3>${esc(l.title)}</h3><small>${esc(l.note||'课内词语巩固')}</small></div><span class="count">${lessonWords(l).length} 个词</span>${icon('chevron')}</button>`).join('')}</div><div class="note-box mt">${icon('info')}<span>先听词语，再写汉字；也可以练拼音。词表词与自编补充会分别标记，具体听写范围可与老师要求对照。</span></div>`;}
function findLesson(id){for(const b of curriculum)for(const u of b.units){const l=u.lessons.find(l=>l.id===id);if(l)return {b,u,l};}return null;}
function lessonPage(){const f=findLesson(route.id);if(!f)return booksPage();const {b,u,l}=f;return `<div class="breadcrumb"><button data-action="nav" data-page="books">${esc(b.title)}</button>${icon('chevron')}<span>第${u.number}单元</span></div>${titleBlock(`第 ${esc(l.number)} 课`,esc(l.title),`${lessonWords(l).length} 个听写词 · ${esc(l.note||'课内词语')}`)}<div class="card mb"><div class="row between wrap"><div><h3>准备好纸笔，或者直接在屏幕上写</h3><p class="tip mt-sm">听写时词语会藏起来。写完揭晓，再认真对照。</p></div><div class="row wrap">${btn('练习拼音','lesson-start','',`data-id="${l.id}" data-mode="type" ${lessonWords(l).length?'':'disabled'}`)}${btn(`${icon('sound')}开始本课听写`,'lesson-start','primary',`data-id="${l.id}" ${lessonWords(l).length?'':'disabled'}`)}</div></div></div>${!lessonWords(l).length?'<div class="note-box mb">本课未列教材词语表条目。可返回课文听写，切换「教材词＋补充词」练习本课原创组词。</div>':''}<div class="section-head"><h2>本课词语</h2><small>点词语听一遍</small></div><div class="word-grid">${lessonWords(l).map(w=>`<button class="word" data-action="follow" data-id="${w.id}"><span class="py">${esc(w.pinyin)}</span><strong>${esc(w.text)}</strong><small>${w.sourceType==='supplement'||w.supplement?'自编补充':'听音 · 跟读'}</small></button>`).join('')}</div>`;}
function reviewPage(){const all=Object.values(state.mistakes).filter(m=>catalog.has(m.id)).sort((a,b)=>a.due-b.due);const filter=route.filter||'active';const list=all.filter(m=>filter==='due'?m.streak<3&&m.due<=Date.now():filter==='mastered'?m.streak>=3:m.streak<3);return `${titleBlock('错一次，也是一次发现','错题小本','先理解差别，再隔天复习。每一次再见面，都更熟悉一点。',btn(`${icon('review')}开始到期复习`,'review-start','primary',dueMistakes().length?'':'disabled'))}<div class="tabs" aria-label="错题范围">${[['active','需要巩固',activeMistakes().length],['due','今天到期',dueMistakes().length],['mastered','已巩固',all.filter(m=>m.streak>=3).length]].map(([id,t,n])=>`<button data-action="review-filter" data-id="${id}" class="${filter===id?'selected':''}">${t} ${n}</button>`).join('')}</div>${list.length?`<div class="lesson-list mt">${list.map(m=>{const q=catalog.get(m.id);return `<div class="card review-row"><button data-action="follow" data-id="${q.id}" aria-label="听${esc(q.text)}">${icon('sound')}</button><div class="grow"><div><span class="py">${esc(q.pinyin)}</span> <span>${esc(q.text)}</span></div><div class="details">${esc(q.source)} · 错 ${m.errors} 次 · 复习答对 ${m.streak}/3${m.reason?` · ${esc(m.reason)}`:''}</div></div><span class="tag">${m.streak>=3?'已巩固':m.due<=Date.now()?'今天复习':new Intl.DateTimeFormat('zh-CN',{month:'numeric',day:'numeric'}).format(m.due)+'再练'}</span></div>`;}).join('')}</div>${filter!=='mastered'?`<div class="row mt">${btn('提前练一练','review-early','')}<small>提前练习不计入间隔复习次数。</small></div>`:''}`:`<div class="card empty mt"><div class="empty-icon">${icon('leaf')}</div><h2>${filter==='due'?'今天的复习完成啦':filter==='mastered'?'给记忆一点时间':'这里还没有需要巩固的题'}</h2><p>${filter==='mastered'?'错题在不同日期的复习中答对 3 次，就会来到这里。':'去做一组练习吧，写错的音和词会自动收进小本子。'}</p>${btn('去练拼音','nav','primary',`data-page="pinyin"`)}</div>`}<div class="note-box mt">${icon('info')}<span>写错后隔 1 天再练；答对后依次隔 3 天、7 天再练，第三次到期复习答对后记为已巩固。看过答案后立即改对，或提前练习，都不算已经巩固。</span></div>`;}
function sessionStart(items,config){if(!items.length){notify('所选范围没有教材词，可切换为教材词＋补充词。');return;}const start=()=>{if(dialog.open)dialog.close();state.session=createSession(items,config);persist();go('practice');};if(state.session&&state.session.index<state.session.items.length){openDialog('还有一组练习没完成',`<p>已完成的题目都已保存。开始新练习会替换当前未完成的练习。</p><div class="row mt">${btn('继续上一组','resume','primary')}${btn('开始新练习','confirm-start')}</div>`);pendingStart=start;}else start();}
let pendingStart=null,inputComposing=false;
function practice(){const s=state.session;if(!s)return home();if(s.index>=s.items.length)return summary();const q=s.items[s.index],r=s.results.find(r=>r.index===s.index);const mode=modeFor(s);const typed=mode==='type',write=mode==='write',choose=mode==='choose'&&q.options;const reveal=s.revealed||!!r;
 return `<div class="question"><div class="practice-header"><button class="text-btn" data-action="pause">${icon('back')}暂停并保存</button><span class="text-small muted">${esc(s.title)}</span><span class="py">${s.index+1} / ${s.items.length}</span></div><div class="progress-track" role="progressbar" aria-label="练习进度" aria-valuenow="${s.index}" aria-valuemin="0" aria-valuemax="${s.items.length}"><div class="progress-fill" style="width:${s.index/s.items.length*100}%"></div></div><div class="practice-listen"><div class="question-prompt"><span class="chip mb">${typed?'独立拼写':choose?'听音辨认':'听写对照'}</span><div class="kicker">${s.review?'再练一次，看看记住了吗':'先听声音，再作答'}</div><h1>${choose?'你听到了哪个音？':typed?'听一听，拼出它的拼音':q.kind==='pinyin'?'听一听，写出拼音':'听一听，写出这个词语'}</h1><p>${choose?'先点喇叭听清楚；不确定时再慢听。':typed?'记得写声调；可以用下方的拼音键盘。':write?'用手指或 Apple Pencil 在下面写。':'在纸上写好，再点「看答案」。'}</p></div><div class="listen"><button class="listen-big" data-action="listen" aria-label="播放题目声音">${icon('sound')}</button><div class="stack" style="gap:4px"><button class="text-btn" data-action="listen-slow">${icon('sound')}更慢听一遍</button>${!choose&&!typed&&!reveal?`<button class="text-btn" data-action="switch-write">${icon(write?'book':'pencil')}${write?'改用纸上写':'改用屏幕写'}</button>`:''}</div></div><div class="listen-status" id="audio-status" role="status">${s.heard?'可以再次播放':'点一下喇叭开始听'}</div></div><div class="practice-answer">
 ${choose?`<div class="options">${q.options.map(o=>`<button class="option py ${reveal?(o===q.pinyin?'correct':r?.answer===o?'wrong':''):''}" data-action="answer-choice" data-answer="${esc(o)}" ${reveal?'disabled':''}>${esc(o)}${reveal&&o===q.pinyin?icon('check'):''}</button>`).join('')}</div>`:typed?`<form id="answer-form" novalidate><label class="sr-only" for="answer-input">你的拼音答案</label><input id="answer-input" class="answer-input" placeholder="在这里拼一拼…" value="${esc(s.draft)}" autocapitalize="none" autocomplete="off" spellcheck="false" ${reveal?'readonly':''} aria-describedby="input-help"><p id="input-help" class="tip mt-sm">声调也可以输入数字：例如 ma1 → mā，lv4 → lǜ。</p>${!reveal?keyboard():''}<div class="practice-actions">${!reveal?'<button type="submit" class="btn primary">写好了，检查答案</button>':''}</div></form>`:write?`<div class="writing-panel mt"><div class="writing-tools"><span>${q.kind==='word'?'写汉字，也可以在旁边注拼音':'在四线格中写拼音'}</span><div>${btn('撤销一笔','undo','small',reveal?'disabled':'')}${btn('清空','clear-pad','small',reveal?'disabled':'')}</div></div><div class="canvas-wrap ${q.kind==='word'?'hanzi':''}"><canvas id="writing" aria-label="手写练习区；也可切换纸上书写" ${reveal?'style="pointer-events:none"':''}></canvas></div><p class="tip mt-sm">保留你的笔迹，稍后自己对照；不会自动识别手写。</p></div>`:`<div class="card empty mt"><div class="empty-icon">${icon('pencil')}</div><h3>在纸上认真写一写</h3><p>写完再看答案，让家长帮忙检查也可以。</p></div>`}
 ${!choose&&!typed&&!reveal?`<div class="practice-actions">${btn('写好了，看答案','reveal','primary')}</div>`:''}
 ${reveal?`<section class="feedback ${r&&!r.correct?'wrong':''}" aria-live="polite"><div class="row between"><strong>${!r?'对照一下，哪里一样、哪里不同？':r.correct?'这一次，写对了！':'发现一个需要再练的地方'}</strong>${icon(r?.correct?'check':'leaf')}</div><div class="answer py mt-sm">${esc(q.pinyin)}<span class="han">${esc(q.text)}</span></div>${r&&!r.correct&&r.answer&&r.answer!=='手写自评'&&r.answer!=='纸上自评'?`<p>你的答案：<span class="py">${esc(r.answer)}</span></p>`:''}${r&&!r.correct&&typed?`<div class="note-box mt-sm">${esc(pinyinFeedback(r.answer,q.pinyin))}</div>`:''}<p class="tip">${esc(q.tip||q.explain||'对照答案检查，再听一次正确读音。')}</p>${!choose?btn(`${icon('sound')}慢听正确读音`,'listen-answer','small'):''}${r&&!r.correct?`<div class="row wrap mt-sm"><small>我想重点注意：</small>${['声母','韵母','声调','汉字'].map(reason=>`<button class="chip" data-action="reason" data-reason="${reason}" aria-pressed="${state.mistakes[q.id]?.reason===reason}">${state.mistakes[q.id]?.reason===reason?'✓ ':''}${reason}</button>`).join('')}</div>`:''}<div class="practice-actions">${!r?btn('还要练练','self-grade','danger',`data-correct="false"`)+btn('写对了','self-grade','primary',`data-correct="true"`):btn(`${s.index+1===s.items.length?'查看本次成果':'下一题'} ${icon('arrow')}`,'next','primary')}</div></section>`:''}</div></div>`;}
function keyboard(){return `<div class="keyboard" aria-label="拼音键盘">${['qwertyuiop','asdfghjkl','zxcvbnmü'].map(row=>`<div class="keyboard-row">${[...row].map(l=>`<button type="button" data-action="key" data-key="${l}">${l}</button>`).join('')}</div>`).join('')}<div class="keyboard-row">${[['1','一声 ˉ'],['2','二声 ˊ'],['3','三声 ˇ'],['4','四声 ˋ'],['5','轻声']].map(([n,t])=>`<button type="button" class="tone" data-action="tone" data-tone="${n}">${t}</button>`).join('')}</div><div class="keyboard-row"><button type="button" class="tone" data-action="key" data-key=" ">空格</button><button type="button" class="tone" data-action="key" data-key="'">隔音 ’</button><button type="button" class="tone" data-action="backspace">退一格</button><button type="button" class="tone" data-action="clear-input">清空</button></div></div>`;}
function summary(){const s=state.session;if(!s)return home();const right=s.results.filter(r=>r.correct).length,wrong=s.results.filter(r=>!r.correct);return `<div class="summary"><div class="summary-art">🌱</div><div class="kicker">今天的小进步</div><h1>认真练过，就在慢慢长大。</h1><p class="muted mt-sm">${esc(s.title)} · 本组练习已完成</p><div class="score">${right}<small> / ${s.items.length} 题正确</small></div><div class="note-box" style="text-align:left">${icon('leaf')}<span>${wrong.length?`发现了 ${wrong.length} 道需要巩固的题，已放入错题小本。明天再见面时，试试独立答出来。`:'这一组全部答对了！休息一下，让眼睛也放个小假。'}</span></div><div class="practice-actions">${s.mode==='choose'?btn('同组再练独立拼写','practice-next-stage','primary'):''}${btn('回到今日练习','finish',s.mode==='choose'?'':'primary')}${wrong.length?btn('看看错在哪里','nav','',`data-page="review"`):btn('再选一个专项','nav','',`data-page="pinyin"`)}</div>${wrong.length?`<div class="section-head"><h2>再看一眼这几个</h2></div><div class="word-grid">${wrong.map(r=>{const q=catalog.get(r.id)||s.items.find(q=>q.id===r.id);return `<button class="word" data-action="follow" data-id="${q.id}"><span class="py">${esc(q.pinyin)}</span><strong>${esc(q.text)}</strong></button>`;}).join('')}</div>`:''}</div>`;}
function render(){pad?.destroy();pad=null;let body;switch(route.page){case'literacy':body=literacy.render(route);break;case'pinyin':body=pinyinPage();break;case'topic':body=topicPage();break;case'chart':body=chartPage();break;case'books':body=booksPage();break;case'lesson':body=lessonPage();break;case'review':body=reviewPage();break;case'practice':body=practice();break;case'summary':body=summary();break;default:body=home();}
 app.innerHTML=shell(body);document.title=({literacy:'语文积累',home:'今日练习',pinyin:'拼音专项',topic:'专项练习',chart:'拼音图谱',books:'课文听写',lesson:'本课听写',review:'错题小本',practice:'听写练习',summary:'本次成果'}[route.page]||'今日练习')+' · 拼音小花园';
 if(route.page==='literacy')literacy.bind();
 if($('#writing'))pad=drawing($('#writing'),state.session.strokes||[],strokes=>{state.session.strokes=strokes;persist();});
 if($('#answer-input'))$('#answer-input').addEventListener('input',e=>{state.session.draft=e.target.value.slice(0,120);persist();});
 if($('#answer-form'))$('#answer-form').addEventListener('submit',e=>{e.preventDefault();if(inputComposing)return;const s=state.session;if(s.revealed)return;if(!canSubmit(s)){notify('先点喇叭听完题目，再检查答案。');return;}if(!s.draft.trim()){notify('先写一个拼音，再检查。');$('#answer-input').focus();return;}grade(gradePinyin(s.draft,s.items[s.index].pinyin),normalizePinyin(s.draft));});
}
function grade(correct,answer){if(stale)return;const old=state.session;const next=recordAnswer(old,correct,answer);if(next===old)return;state.session=next;const q=next.items[next.index],now=Date.now();const m=updateMistake(state.mistakes[q.id],q,correct,now,next.review&&modeFor(next)!=='choose');if(m)state.mistakes[q.id]=m;state.history.push({key:`${next.id}-${next.index}`,id:q.id,correct,at:now,mode:modeFor(next)});state.history=state.history.slice(-5000);persist();render();$('.feedback')?.scrollIntoView({block:'nearest',behavior:'smooth'});}
async function play(text,slow=false){demoEpoch++;const status=$('#audio-status');if(status)status.textContent='正在播放…';try{const completed=await speak(text,slow?Math.min(SLOW_RATE,state.settings.rate):state.settings.rate);if(completed&&status?.isConnected)status.textContent='听清了吗？可以再听一次。';return completed;}catch(e){if(status?.isConnected)status.textContent=e.message;notify(e.message);return false;}}
function follow(q){openDialog('听一听，再跟着读',`<div style="text-align:center"><div class="answer py">${esc(q.pinyin)}</div><div style="font-size:34px">${esc(q.text||q.example)}</div><p class="tip mt-sm">${esc(q.tip||q.explain||'先听一遍，再模仿着读。')}</p><div class="practice-actions">${btn(`${icon('sound')}听例音`,'dialog-sound','primary',`data-text="${esc(q.text||q.example)}"`)}${btn('慢速播放','dialog-slow','',`data-text="${esc(q.text||q.example)}"`)}</div><div class="record-box"><button class="btn" id="record-button" data-action="record">${icon('mic')}录下我的跟读</button><p class="tip mt-sm" id="record-status">最长 30 秒，仅在本页回听，不上传，也不自动评分。</p><div id="record-player"></div></div></div>`);play(q.text||q.example);}
function settings(){openDialog('家长设置',`<p class="tip mb">让练习适合孩子的节奏。学习记录只保存在这台设备的当前浏览器中。</p><div class="settings-grid"><label class="field" for="setting-rate">朗读速度<select id="setting-rate">${SPEECH_RATES.map(([v,t])=>`<option value="${v}" ${state.settings.rate===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field" for="setting-mode">默认听写方式<select id="setting-mode"><option value="write" ${state.settings.mode==='write'?'selected':''}>在屏幕上手写，对照自评</option><option value="paper" ${state.settings.mode==='paper'?'selected':''}>在纸上写，对照自评</option><option value="type" ${state.settings.mode==='type'?'selected':''}>输入拼音，自动检查</option></select></label><label class="field" for="setting-count">每日拼音练习题数<select id="setting-count">${[6,10,15].map(n=>`<option value="${n}" ${state.settings.count===n?'selected':''}>${n} 道题</option>`).join('')}</select></label>${btn('保存设置','save-settings','primary')}</div><div class="divider"></div><h3 class="small-title">声音与离线使用</h3><p class="tip">朗读采用普通话合成语音，图谱播放完整例字音。首次打开需要联网。下载声音包后，可在离线时进行内置练习。系统清理网站数据后，需要重新下载。</p><div class="row wrap mt-sm">${btn('试听普通话','dialog-sound','',`data-text="你好，我们一起练习拼音。"`)}${btn(`${icon('cloud')}下载离线声音包`,'offline','',offlineBusy?'disabled':'')}</div><div id="offline-status" class="tip mt-sm" role="status"></div><div class="divider"></div><h3 class="small-title">学习记录备份</h3><p class="tip">换设备、清理浏览器前请先导出。导入会合并已知题目的记录，不覆盖更晚的错题结果。笔迹和跟读录音不包含在备份中。</p><div class="row wrap mt-sm">${btn('导出学习记录','export')}${btn('导入备份','import')}<input id="import-file" type="file" accept="application/json,.json" hidden></div><div class="divider"></div><div class="row wrap">${btn('教材版本与来源','sources','small')}${btn('使用说明','help','small')}</div>`);if('caches'in window)caches.open(AUDIO_CACHE).then(async cache=>{const files=[...new Set(Object.values(audioMap))];const hits=await Promise.all(files.map(f=>cache.match(new URL(f,location.href).href)));const count=hits.filter(Boolean).length;const el=$('#offline-status');if(el&&!offlineBusy)el.textContent=count===files.length?`新版慢速声音包已完整下载（${count}段）。`:`新版慢速声音已下载 ${count}/${files.length} 段，点击下载可继续补全。`;}).catch(()=>{const el=$('#offline-status');if(el)el.textContent='暂时无法读取声音缓存，联网时仍可练习。';});}
function sources(){openDialog('教材版本与内容来源',`<p>按人教统编语文「根据2022年版课程标准修订」版本整理，二年级上册封面标注「2024年审核通过」，依据已确认的修订教材核对，核验日期：2026年11月9日。资源更新时间不等于教材版次。</p>${curriculum.map(b=>`<div class="mt"><h3>${esc(b.title)}</h3><p class="tip">${esc(b.edition)}<br>${esc(b.note||'官方词语表与自编补充分别标记。')}</p>${b.sourceUrl?`<a target="_blank" rel="noopener noreferrer" href="${esc(b.sourceUrl)}">查看官方教材来源 ↗</a>`:''}</div>`).join('')}<div class="divider"></div><p class="tip">练习不是人教社官方软件。教材课名和词语用于同步巩固，未复制整篇课文。自编补充用于古诗、园地及容易混淆的拼音练习；学校的听写范围以老师要求为准。</p><p class="tip mt-sm">图谱播放完整例字的读音，声母应留意开头的辅音；例字音不等于独立声母录音。拼音题按词典本调书写，涉及变调会在说明中提示。</p>`);}
function help(){openDialog('怎样用小花园练习',`<ol class="instructions"><li><strong>拼音专项：</strong>先选易混类型，听音辨一辨，再尝试输入拼音或手写。</li><li><strong>课文听写：</strong>选择上下册、单元、课名，听声音后写词语。写好揭晓，逐字对照并如实标记。</li><li><strong>跟读：</strong>点击拼音或词语卡片，听例音、录下自己的读音，再回听比较。软件不做发音评分。</li><li><strong>错题：</strong>写错自动收集，到期后再独立作答。跨日期答对三次记为已巩固。</li></ol><p class="tip">一次练 6～15 题即可。儿童独立使用前，建议家长先试听一组并演示如何对照批改。</p>`);}
async function downloadOffline(){if(offlineBusy)return;if(!('caches'in window)||!('serviceWorker'in navigator)){notify('当前浏览器不支持离线保存，请使用 Safari 打开正式网址。');return;}offlineBusy=true;const status=$('#offline-status');try{await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('离线功能未准备好，请保持联网并重新打开应用。')),15000);navigator.serviceWorker.ready.then(r=>{clearTimeout(timer);resolve(r);},e=>{clearTimeout(timer);reject(e);});});const cache=await caches.open(AUDIO_CACHE);const files=[...new Set(Object.values(audioMap))];let count=0;const setStatus=()=>{if(status?.isConnected)status.innerHTML=`正在准备离线声音 ${count} / ${files.length}<progress class="offline-progress" max="${files.length}" value="${count}"></progress>`;};setStatus();for(let i=0;i<files.length;i+=4){await Promise.all(files.slice(i,i+4).map(async f=>{const u=new URL(f,location.href);if(!await cache.match(u.href)){const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),20000);let r;try{r=await fetch(u.href,{cache:'reload',signal:controller.signal});}finally{clearTimeout(timeout);}if(!r.ok||!r.headers.get('content-type')?.startsWith('audio/'))throw Error('部分声音没有下载成功，请保持联网后重试。');await cache.put(u.href,r);}count++;setStatus();}));}if(!files.length)throw Error('声音包尚未就绪。');if(status?.isConnected)status.textContent=`已准备好 ${files.length} 段声音，可以离线练习了。`;await Promise.all((await caches.keys()).filter(k=>k.startsWith('pinyin-audio-')&&k!==AUDIO_CACHE).map(k=>caches.delete(k)));notify('新版慢速声音下载完成。');}catch(e){if(status?.isConnected)status.textContent=e.message;notify(e.message||'下载失败，请联网重试。');}finally{offlineBusy=false;}}
function exportBackup(){const b={version:1,history:state.history,mistakes:state.mistakes,settings:state.settings,literacy:state.literacy};const blob=new Blob([JSON.stringify(b,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`拼音小花园-学习备份-${localDay()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);notify('备份已导出，请保存到「文件」。');}
async function importBackup(file){try{if(!file||file.size>3*1024*1024)throw Error('请选择不超过 3MB 的学习备份 JSON 文件。');const data=JSON.parse(await file.text());state=mergeBackup(state,data,catalog);persist();render();notify('学习记录已合并。');}catch(e){notify(`无法导入：${e.message}`);}}
function editInput(key,action){const el=$('#answer-input');if(!el||state.session.revealed)return;let v=state.session.draft||'',start=el.selectionStart??v.length,end=el.selectionEnd??v.length;
 if(action==='tone'){const before=v.slice(0,start);const m=before.match(/[a-züv:āáǎàēéěèīíǐìōóǒòūúǔùǖǘǚǜ]+$/i);if(!m){notify('先输入一个音节，再选声调。');return;}const base=m[0].normalize('NFD').replace(/[\u0304\u0301\u030c\u0300]/g,'').normalize('NFC');const replacement=normalizePinyin(base+key);v=before.slice(0,-m[0].length)+replacement+v.slice(end);start=before.length-m[0].length+replacement.length;}
 else if(action==='backspace'){v=v.slice(0,start===end?Math.max(0,start-1):start)+v.slice(end);start=Math.max(0,start-(start===end?1:0));}else if(action==='clear'){v='';start=0;}else{v=v.slice(0,start)+key+v.slice(end);start+=key.length;}state.session.draft=v.slice(0,120);el.value=state.session.draft;el.setSelectionRange(start,start);persist();}
app.addEventListener('pointerdown',e=>{if(e.target.closest('[data-action="key"],[data-action="tone"],[data-action="backspace"],[data-action="clear-input"]'))e.preventDefault();});
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,d=el.dataset;
 if(a.startsWith('lit-')){literacy.handle(a,d);return;}
 // Safari touch clicks do not focus buttons; capture dialog triggers for focus restoration.
 if(['settings','sources','help','follow','chart-sound','start-topic','daily','lesson-start','unit-start','review-start','review-early'].includes(a))el.focus({preventScroll:true});
 if(stale&&!['export','close-dialog','reload'].includes(a)){notify('另一页已更新学习记录，请先刷新。');return;}
 switch(a){
 case'nav':if(dialog.open)dialog.close();go(d.page);break;
 case'settings':settings();break;case'sources':sources();break;case'help':help();break;case'close-dialog':dialog.close();break;
 case'tone-demo':await toneDemo(d.tone);break;case'tone-pair':await toneDemo(d.pair);break;
 case'word-range':state.includeSupplements=d.include==='true';persist();render();break;
 case'filter-topic':route.kind=d.kind;render();break;
 case'topic':go('topic',{id:d.id});break;case'chart':go('chart');break;case'chart-group':go('chart',{group:d.id});break;
 case'chart-sound':{const g=soundGroups.find(g=>g.id===d.group);const q=g.items[Number(d.index)];follow({...q,text:q.example,tip:(q.tip||'')+' 播放的是完整例字音。'});break;}
 case'follow':{const q=catalog.get(d.id);if(q)follow(q);break;}
 case'dialog-sound':play(d.text);break;case'dialog-slow':play(d.text,true);break;
 case'start-topic':{const t=topics.find(t=>t.id===d.id);let mode=d.mode;if(mode==='write'&&state.settings.mode==='paper')mode='paper';sessionStart(selectPractice(t.items.map(q=>catalog.get(q.id)),state.history,state.mistakes,state.settings.count),{title:t.title,mode,origin:'pinyin'});break;}
 case'daily':{const items=selectPractice(allPinyin(),state.history,state.mistakes,state.settings.count).map((q,i)=>({...q,practiceMode:i%3===2?'type':'choose'}));sessionStart(items,{title:'今日拼音练习',mode:'choose',origin:'home',review:true});break;}
 case'book':state.book=d.id;state.unit=1;persist();render();break;case'unit':state.unit=Number(d.number);persist();render();break;
 case'lesson':go('lesson',{id:d.id});break;
 case'lesson-start':{const f=findLesson(d.id);sessionStart(lessonWords(f.l),{title:f.l.title,mode:d.mode||state.settings.mode,origin:'books'});break;}
 case'unit-start':{const b=curriculum.find(b=>b.id===state.book)||curriculum[0],u=b.units.find(u=>u.id===d.id);let items=u.lessons.flatMap(lessonWords);items=shuffled(items);if(d.count!=='all')items=items.slice(0,Number(d.count));sessionStart(items,{title:`${b.title} · 第${u.number}单元`,mode:state.settings.mode,origin:'books'});break;}
 case'confirm-start':pendingStart?.();pendingStart=null;break;
 case'resume':if(dialog.open)dialog.close();go('practice');break;
 case'pause':persist();go(state.session.origin||'home');notify('已保存，随时可以继续。');break;
 case'listen':case'listen-slow':case'listen-answer':{const s=state.session;if(!s)return;const index=s.index;const completed=await play(dictationText(s.items[index],modeFor(s)),a!=='listen');if(completed&&state.session===s&&s.index===index&&route.page==='practice'){s.heard=true;persist();}break;}
 case'answer-choice':{const s=state.session;if(!canSubmit(s)){notify('先点喇叭听一听，再选答案。');return;}grade(d.answer===s.items[s.index].pinyin,d.answer);break;}
 case'reveal':if(!canSubmit(state.session)){notify('先点喇叭听完题目，再看答案。');break;}state.session.revealed=true;persist();render();$('.feedback')?.scrollIntoView({block:'nearest',behavior:'smooth'});break;
 case'self-grade':if(!state.session?.revealed)break;grade(d.correct==='true',modeFor(state.session)==='write'?'手写自评':'纸上自评');break;
 case'next':{const s=state.session;if(!s.results.some(r=>r.index===s.index))return;stopAudio();s.index++;s.revealed=false;s.heard=false;s.draft='';s.strokes=[];persist();go(s.index>=s.items.length?'summary':'practice');break;}
 case'practice-next-stage':{const s=state.session;if(s.index<s.items.length)break;sessionStart(s.items.map(({practiceMode,...q})=>q),{title:s.title+' · 独立拼写',mode:'type',origin:s.origin,review:false});break;}
 case'finish':state.session=null;persist();go('home');break;
 case'switch-write':{const s=state.session;s.mode=s.mode==='write'?'paper':'write';persist();render();break;}
 case'undo':pad?.undo();break;case'clear-pad':pad?.clear();break;
 case'key':editInput(d.key,'key');break;case'tone':editInput(d.tone,'tone');break;case'backspace':editInput('','backspace');break;case'clear-input':editInput('','clear');break;
 case'reason':{const q=state.session.items[state.session.index];if(state.mistakes[q.id]){state.mistakes[q.id].reason=d.reason;persist();render();}break;}
 case'review-filter':route.filter=d.id;render();break;
 case'review-start':case'review-early':{const items=(a==='review-start'?dueMistakes():activeMistakes()).map(m=>catalog.get(m.id));if(!items.length){notify('暂时没有到期的题目。');return;}sessionStart(items,{title:a==='review-start'?'错题到期复习':'错题提前练习',mode:'write',review:a==='review-start',origin:'review'});break;}
 case'save-settings':state.settings={rate:Number($('#setting-rate').value),mode:$('#setting-mode').value,count:Number($('#setting-count').value)};persist();dialog.close();render();notify('练习设置已保存。');break;
 case'offline':downloadOffline();break;case'export':exportBackup();break;case'import':$('#import-file').click();break;
 case'record':{if(recording){stopRecording();recording=false;return;}stopAudio();const b=$('#record-button'),status=$('#record-status');b.disabled=true;status.textContent='正在打开麦克风…';try{const started=await startRecording(url=>{recording=false;if(!$('#record-player'))return;$('#record-player').innerHTML=`<audio controls src="${url}"></audio>`;b.innerHTML=`${icon('mic')}重新录一遍`;b.classList.remove('recording');b.disabled=false;status.textContent='听听自己的声音，再与例音比较。关闭本页就会删除录音。';});if(!b.isConnected||!started)return;recording=true;b.disabled=false;b.innerHTML='停止录音';b.classList.add('recording');status.textContent='正在录音，30 秒后自动停止。';}catch(e){b.disabled=false;status.textContent=e.message;notify(e.message);}break;}
 case'reload':location.reload();break;
 }
});
document.addEventListener('compositionstart',e=>{if(e.target.id==='answer-input')inputComposing=true;});
document.addEventListener('compositionend',e=>{if(e.target.id==='answer-input')inputComposing=false;});
document.addEventListener('change',e=>{if(e.target.id==='import-file')importBackup(e.target.files[0]);});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){stale=true;openDialog('另一页更新了学习记录',`<p>为避免覆盖另一页的进度，请刷新后继续。当前已保存的题目会保留。</p><div class="practice-actions">${btn('刷新并读取记录','reload','primary')}${btn('先导出本页记录','export')}</div>`);}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopAudio();releaseRecording();recording=false;persist();const b=$('#record-button');if(b){b.innerHTML=`${icon('mic')}录下我的跟读`;b.classList.remove('recording');b.disabled=false;$('#record-status').textContent='切到后台已停止录音，请重新录制。';}}});
window.addEventListener('pagehide',cleanup);
window.addEventListener('online',()=>{notify('网络已连接。');});
window.addEventListener('offline',()=>{notify('已离线，下载过的内容可以继续练习。');});
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').then(reg=>{const offer=()=>{if(!reg.waiting)return;notify('新版已准备好。保存练习并重新打开应用后生效。');};offer();reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)offer();});});}).catch(()=>notify('离线功能暂未开启，联网时仍可正常练习。'));
render();

function syncViewport(){const viewport=window.visualViewport;document.documentElement.style.setProperty('--visible-height',`${viewport?.height||window.innerHeight}px`);document.documentElement.style.setProperty('--visible-top',`${viewport?.offsetTop||0}px`);}
syncViewport();window.visualViewport?.addEventListener('resize',syncViewport);window.visualViewport?.addEventListener('scroll',syncViewport);window.addEventListener('resize',syncViewport);

function toneLab(){const tones=topics.find(t=>t.id==='four-tones').items.slice(0,4);return `<section class="tone-lab mt" aria-label="声调慢听小练习"><div class="row between wrap"><div><h2>先把四个声调听清楚</h2><p class="tip">点一下，慢慢听。先跟着读，再听两声的差别。</p></div>${btn('开始声调听辨','start-topic','small primary','data-id="four-tones" data-mode="choose"')}</div><div class="tone-grid mt-sm">${tones.map((q,i)=>`<button class="tone-card" data-action="tone-demo" data-tone="${i+1}" aria-label="慢听第${i+1}声，${esc(q.text)}"><span class="tone-shape" aria-hidden="true">${['—','↗','∨','↘'][i]}</span><span class="py">${q.pinyin}</span><span>${q.text} · 第${i+1}声</span></button>`).join('')}</div><div class="row wrap mt-sm">${[['12','一声 / 二声'],['23','二声 / 三声'],['34','三声 / 四声']].map(([pair,label])=>btn(`${icon('sound')}${label}`,'tone-pair','small',`data-pair="${pair}"`)).join('')}</div><p class="tip tone-status" id="tone-status" role="status">一声平，二声扬，三声单独慢读时先降再升，四声降。例音为合成普通话。</p></section>`;}
async function toneDemo(key){const examples=topics.find(t=>t.id==='four-tones').items.slice(0,4);const sequence=[...key].map(n=>examples[Number(n)-1]).filter(Boolean);const own=++demoEpoch;stopAudio();const status=$('#tone-status');try{for(let i=0;i<sequence.length;i++){if(own!==demoEpoch||!status?.isConnected)return;const q=sequence[i];status.textContent=`正在慢听：${q.text} ${q.pinyin}。注意声音的高低变化。`;const completed=await speak(q.text,Math.min(state.settings.rate,SLOW_RATE));if(!completed||own!==demoEpoch)return;if(i<sequence.length-1)await new Promise(resolve=>setTimeout(resolve,700));}if(status?.isConnected&&own===demoEpoch)status.textContent='听完了。可以再听一次，也可以开始声调听辨。';}catch(e){if(status?.isConnected&&own===demoEpoch)status.textContent=e.message;}}
